function pusPort(): int { $s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if($s===false)throw new TestFailure('allocate port');$n=(string)stream_socket_get_name($s,false);fclose($s);return (int)substr($n,strrpos($n,':')+1); }
function pusStart(array $env): array { $p=pusPort();$c=['/usr/bin/env','-i'];foreach($env as$k=>$v)$c[]=$k.'='.$v;$c=[...$c,PHP_BINARY,'-d','expose_php=0','-S','127.0.0.1:'.$p,dirname(__DIR__,2).'/public/router.php'];$r=proc_open($c,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2));if(!is_resource($r))throw new TestFailure('start server');fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$until=microtime(true)+5;while(microtime(true)<$until){$s=@stream_socket_client("tcp://127.0.0.1:$p",$e,$m,.1);if($s!==false){fclose($s);return ['process'=>$r,'pipes'=>$pipes,'port'=>$p];}usleep(50000);}throw new TestFailure('server listen'); }
function pusStop(?array $s): void { if($s===null||!is_resource($s['process']))return;if(proc_get_status($s['process'])['running'])proc_terminate($s['process']);foreach([1,2]as$i)if(is_resource($s['pipes'][$i])){stream_get_contents($s['pipes'][$i]);fclose($s['pipes'][$i]);}proc_close($s['process']); }
function pusRequest(int $p,string $method,string $target): array { $s=stream_socket_client("tcp://127.0.0.1:$p",$e,$m,5);if($s===false)throw new TestFailure('connect');fwrite($s,"$method $target HTTP/1.1\r\nHost: ui.example\r\nConnection: close\r\n\r\n");fflush($s);stream_socket_shutdown($s,STREAM_SHUT_WR);$raw='';while(!feof($s))$raw.=(string)fread($s,65536);fclose($s);[$h,$b]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$ls=explode("\r\n",$h);preg_match('/^HTTP\/\d\.\d (\d{3})/',(string)array_shift($ls),$m);$headers=[];foreach($ls as$l)if(str_contains($l,':')){[$k,$v]=explode(':',$l,2);$headers[strtolower(trim($k))][]=trim($v);}return ['status'=>(int)($m[1]??0),'headers'=>$headers,'body'=>$b]; }
function pusHeader(array $r,string $n): ?string { $v=$r['headers'][strtolower($n)]??[];return count($v)===1?$v[0]:null; }
function pusGetHead(int $p,string $route): array { $g=pusRequest($p,'GET',$route);$h=pusRequest($p,'HEAD',$route);assertSameValue([$g['status'],pusHeader($g,'content-type'),pusHeader($g,'content-length')],[$h['status'],pusHeader($h,'content-type'),pusHeader($h,'content-length')],'GET HEAD representation parity '.$route);assertSameValue('',$h['body'],'HEAD empty '.$route);return $g; }
function pusDom(array $r,string $why): array { assertSameValue(200,$r['status'],$why.' status');$d=new DOMDocument();$old=libxml_use_internal_errors(true);$ok=$d->loadHTML($r['body'],LIBXML_NONET|LIBXML_NOERROR|LIBXML_NOWARNING);libxml_clear_errors();libxml_use_internal_errors($old);assertSameValue(true,$ok,$why.' parse');return [$d,new DOMXPath($d)]; }
function pusText(DOMDocument $d): string { return preg_replace('/\s+/u',' ',trim($d->textContent))??''; }
function pusStable(array $r): array { unset($r['headers']['date'],$r['headers']['connection']);return $r; }
function pusSnapshot(mysqli $d): string { $all=[];$tables=$d->query('SELECT TABLE_NAME,AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME')->fetch_all(MYSQLI_ASSOC);foreach($tables as$t){$n=$t['TABLE_NAME'];$rows=$d->query("SELECT * FROM `$n`")->fetch_all(MYSQLI_ASSOC);usort($rows,fn($a,$b)=>serialize($a)<=>serialize($b));$all[]=[$t,$rows];}return hash('sha256',serialize($all)); }
function pusTree(string $root): string { $items=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as$f)if($f->isFile())$items[]=[substr($f->getPathname(),strlen($root)),hash_file('sha256',$f->getPathname())];sort($items);return hash('sha256',serialize($items)); }
function pusError(array $r,int $status,string $body,string $why): void { assertSameValue([$status,'text/plain; charset=UTF-8',$body,$status===503?'60':null],[$r['status'],pusHeader($r,'content-type'),$r['body'],pusHeader($r,'retry-after')],$why);foreach(['АО «ЩЛЗ»','Сидоров','4515','SQL','mysqli','Exception','/home/']as$x)assertSameValue(false,str_contains($r['body'],$x),$why.' redacts '.$x); }
function pusConcurrent(int $p,string $route): array { $s=[];foreach([0,1]as$i){$s[$i]=stream_socket_client("tcp://127.0.0.1:$p",$e,$m,5);fwrite($s[$i],"GET $route HTTP/1.1\r\nHost: ui.example\r\nConnection: close\r\n\r\n");fflush($s[$i]);stream_socket_shutdown($s[$i],STREAM_SHUT_WR);} $out=[];foreach($s as$socket){$raw='';while(!feof($socket))$raw.=(string)fread($socket,65536);fclose($socket);[$h,$b]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$out[]=$b;}return $out; }
function pusCssBlock(string $css,string $needle): string { $at=strpos($css,$needle);assertSameValue(true,$at!==false,'CSS block exists '.$needle);$open=strpos($css,'{',$at);if($open===false)throw new TestFailure('CSS block opens '.$needle);$depth=0;for($i=$open,$n=strlen($css);$i<$n;$i++){if($css[$i]==='{')$depth++;elseif($css[$i]==='}'&&--$depth===0)return substr($css,$open+1,$i-$open-1);}throw new TestFailure('CSS block closes '.$needle); }
function pusCssDecl(string $block,string $selector,string $property,string $value): void { $found=false;preg_match_all('/([^{}]+)\{([^{}]*)\}/s',$block,$rules,PREG_SET_ORDER);foreach($rules as$rule){$selectors=array_map(fn($s)=>preg_replace('/\s+/',' ',trim($s)),explode(',',$rule[1]));if(in_array($selector,$selectors,true)&&preg_match('/(?:^|;)\s*'.preg_quote($property,'/').'\s*:\s*'.preg_quote($value,'/').'\s*(?:;|$)/i',$rule[2])===1){$found=true;break;}}assertSameValue(true,$found,'CSS declaration '.$selector.' '.$property.': '.$value); }
